// scanFrame 是严格键扫描的栈帧。
type scanFrame struct {
	isArray bool
	// fields 非 nil 表示这是“固定字段对象”：其中每个键都必须命中 fields
	// （逐字区分大小写），且同一对象内不得重复。nil 表示业务编号表
	// （balances / proposals / vote_proposals）：键是账户名或提案编号，
	// 大小写敏感但允许仅有大小写差异的多个不同编号，只拒绝逐字重复键。
	fields  map[string]bool
	seen    map[string]bool
	atValue bool // 对象帧：下一个待消费 token 是值而非键
	// idKey 非空时，对象内该字段的值用于错误定位（如提案编号）。
	idKey string
	// path 是进入本对象的 JSON 指针式位置，用于错误定位。
	path string
}

