// json tag，必须与当前保存格式逐字一致。业务编号表（balances、
// proposals、vote_proposals）不是固定字段对象，不在此声明。
var (
	strictRootFields = jsonTagSet(storedState{},
		"magic", "version", "initial_treasury", "treasury",
		"balances", "proposals", "receipts", "vote_proposals")
	strictProposalFields = jsonTagSet(storedProposal{},
		"id", "state", "timelock_end", "actions")
	strictReceiptFields = jsonTagSet(Receipt{},
		"proposal_id", "executed_at", "order", "actions")
	strictActionReceiptFields = jsonTagSet(ActionReceipt{},
		"index", "action", "treasury", "recipient")
	strictBalanceUpdateFields = jsonTagSet(BalanceUpdate{},
		"account", "before", "after")
	strictVoteProposalFields = jsonTagSet(storedVoteProposal{},
		"id", "state", "members", "delegations", "quorum",
		"start_at", "deadline", "timelock_end", "actions", "ballots", "tally")
	strictMemberFields     = jsonTagSet(storedMember{}, "id", "weight")
	strictDelegationFields = jsonTagSet(storedDelegation{}, "from", "to")
	strictBallotFields = jsonTagSet(storedBallot{},
		"representative", "weight", "support", "voted_at")
	strictTallyFields = jsonTagSet(storedTally{},
		"for_weight", "against_weight", "tallied_at")
)

// jsonTagSet 仅为在一处集中列出固定字段名；参数类型只起文档作用，
// 实际允许集合以显式列出的 tag 名为准。
func jsonTagSet(_ any, names ...string) map[string]bool {
	m := make(map[string]bool, len(names))
	for _, n := range names {
		m[n] = true
	}
	return m
}

// scanStrictKeys 用一次 json.Decoder token 流完成结构相关的键检查：
//   - 固定字段对象只接受与保存格式逐字一致的字段名：把 treasury 写成
//     Treasury、把票据里的 support 写成 Support 一律拒绝；未知字段仍由
//     解码阶段的 DisallowUnknownFields 拒绝，这里提前给出可定位的原因；
//   - 同一对象内重复键按 JSON 解读后的字符串判定："state" 与 "state"
//     （含不同合法转义写法）是同一个键，state 与 State 不是同一个键；
//   - 业务编号表（balances/proposals/vote_proposals）的键是账户名或
//     提案编号，Audit 与 audit、GIP-1 与 gip-1 都是不同编号，允许共存；
//   - 重复判断只作用于同一个对象，不同记录各自拥有 state 等字段正常。
func scanStrictKeys(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	var stack []*scanFrame
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			if len(stack) != 0 {
				return errors.New("unterminated object or array")
			}
			return nil
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{':
