				// 命中时切换为 map 帧（见下方对象键处理）。
				stack = append(stack, &scanFrame{
					fields: strictRootFields,
					seen:   map[string]bool{},
				})
				if len(stack) >= 2 {
					parent := stack[len(stack)-2]
					if parent.isArray {
						// 修正帧类型：数组元素若是固定字段记录，其字段集
						// 在数组开启时登记在数组帧上（elemFields/path）。
						stack[len(stack)-1].fields = parent.elemFields
						stack[len(stack)-1].path = parent.path + "[]"
						stack[len(stack)-1].idKey = parent.elemIDKey
					}
				}
				continue
			case '[':
				frame := &scanFrame{isArray: true}
				if len(stack) > 0 {
					parent := stack[len(stack)-1]
					if !parent.isArray && parent.atValue {
						// 记录这个数组对应的固定字段，供其中的对象元素
						// 选择字段集；业务表数组（members 等）元素仍是
						// 固定字段记录。
						frame.elemFields, frame.elemIDKey = arrayElementSchema(parent.pendingKey)
						frame.path = joinPath(parent.path, parent.pendingKey)
					}
				}
				stack = append(stack, frame)
				continue
			case '}', ']':
				if len(stack) == 0 {
					return errors.New("unexpected closing delimiter")
				}
				stack = stack[:len(stack)-1]
				// 关闭的容器本身是外层对象的某个“值”，消费完毕后外层等待下一个键。
				if len(stack) > 0 && !stack[len(stack)-1].isArray {
					stack[len(stack)-1].atValue = false
				}
				continue
			}
		default:
			// 标量 token。
		}
		if len(stack) > 0 && !stack[len(stack)-1].isArray {
			frame := stack[len(stack)-1]
			if !frame.atValue {
				// 对象键（json.Decoder 已把转义解读为最终字符串）。
				key, ok := tok.(string)
				if !ok {
					return errors.New("object key must be a string")
				}
				if frame.seen[key] {
					return fmt.Errorf("duplicate key %q%s", key, locationOf(frame))
				}
				frame.seen[key] = true
				if frame.fields != nil && !frame.fields[key] {
					// 固定字段名必须与保存格式逐字一致。这里无法区分
					// “未知字段”与“大小写错写”，统一按非法字段拒绝，
					// 原因里指出字段名与所在记录。
					return fmt.Errorf("unknown or wrong-case field %q%s", key, locationOf(frame))
				}
				// 业务编号表中的对象值：按键名选择记录字段集并携带编号定位。
				if frame.fields == nil && len(stack) == 0 || false {
			}
				frame.atValue = true
				frame.pendingKey = key
			} else {
				frame.atValue = false
				frame.pendingKey = ""
			}
		}
	}
}

func (f *scanFrame) notePendingKeyForOpenObject(child *scanFrame) {
	// 预留（未使用）。
	_ = f
	_ = child
}

