1019	// recInvalidObject（其中任何字段都会被拒绝，随后的正常解码也会拒绝）。
1020	func objectKindUnder(parentKind int, key string) int {
1021		switch parentKind {
1022		case recRoot:
1023			switch key {
1024			case "balances":
1025				return recBalancesMap
1026			case "proposals":
1027				return recProposalsMap
1028			case "vote_proposals":
1029				return recVotesMap
