1047	// arrayElemKind 决定某数组中对象元素的记录类型；标量数组返回 recInvalidObject，
1048	// 因为其内部不应当出现任何对象字段。
1049	func arrayElemKind(parentKind int, key string) int {
1050		switch parentKind {
